def patch_models_live() -> None:
    path = ROOT / "backend/models_live.py"
    text = path.read_text(encoding="utf-8")
    if "offers_enabled" not in text:
        text = text.replace(
            "    updated_at = Column(DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)\n\n    products = relationship(",
            "    updated_at = Column(DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)\n"
            "    offers_enabled = Column(Boolean, default=True, nullable=False)\n\n"
            "    products = relationship(",
            1,
        )
        text = text.replace(
            "    is_pinned = Column(Boolean, default=False, nullable=False)\n    created_at = Column(DateTime, default=datetime.utcnow, nullable=False)\n\n    stream = relationship",
            "    is_pinned = Column(Boolean, default=False, nullable=False)\n"
            "    offers_enabled = Column(Boolean, default=True, nullable=False)\n"
            "    created_at = Column(DateTime, default=datetime.utcnow, nullable=False)\n\n    stream = relationship",
            1,
        )
    path.write_text(text, encoding="utf-8", newline="\n")
    print("patched", path.relative_to(ROOT))


def patch_db_migrate() -> None:
    path = ROOT / "backend/services/db_migrate.py"
    text = path.read_text(encoding="utf-8")
    if "_migrate_live_offer_schema()" not in text:
        text = text.replace(
            "    _migrate_live_auction_schema()\n",
            "    _migrate_live_auction_schema()\n    _migrate_live_offer_schema()\n",
        )
    if "def _migrate_live_offer_schema" not in text:
        text += '''\n\n\ndef _migrate_live_offer_schema() -> None:\n    """Phase 3-3 additive tables for live offers."""\n    import models_live_offer  # noqa: F401\n\n    _add_column_if_missing("live_streams", "offers_enabled", "BOOLEAN DEFAULT 1")\n    _add_column_if_missing("live_products", "offers_enabled", "BOOLEAN DEFAULT 1")\n\n    offer_tables = [\n        ("live_offers", models_live_offer.LiveOffer),\n        ("live_offer_purchase_rights", models_live_offer.LiveOfferPurchaseRight),\n        ("live_offer_audit_logs", models_live_offer.LiveOfferAuditLog),\n        ("live_offer_settings", models_live_offer.LiveOfferSettings),\n    ]\n    for table_name, model in offer_tables:\n        _create_table_if_missing(table_name, model)\n\n    from sqlalchemy.orm import sessionmaker\n    from services.admin_seed import seed_admin_rbac\n\n    Session = sessionmaker(bind=engine)\n    with Session() as db:\n        try:\n            seed_admin_rbac(db)\n        except Exception:\n            db.rollback()\n            logger.exception("live offer schema RBAC seed failed")\n'''
    path.write_text(text, encoding="utf-8", newline="\n")
    print("patched", path.relative_to(ROOT))


def patch_admin_rbac() -> None:
    path = ROOT / "backend/services/admin_rbac.py"
    text = path.read_text(encoding="utf-8")
    perms = [
        '    ("offer.read", "Live offer read", "live"),',
        '    ("offer.create", "Live offer create", "live"),',
        '    ("offer.review", "Live offer review", "live"),',
        '    ("offer.manage", "Live offer manage", "live"),',
    ]
    if "offer.read" not in text:
        text = text.replace(
            '    ("live.broadcast", "',
            "\n".join(perms) + '\n    ("live.broadcast", "',
            1,
        )
    role_additions = {
        '"admin": {': '"admin": {\n        "offer.read",\n        "offer.create",\n        "offer.review",\n        "offer.manage",',
        '"sales_manager": {': '"sales_manager": {\n        "offer.read",\n        "offer.create",\n        "offer.review",\n        "offer.manage",',
        '"support_manager": {': '"support_manager": {\n        "offer.read",\n        "offer.create",',
        '"live_moderator": {': '"live_moderator": {\n        "offer.read",\n        "offer.create",',
    }
    for needle, insert in role_additions.items():
        if needle in text:
            block = text.split(needle, 1)[1].split("}", 1)[0]
            if "offer.read" not in block and insert not in text:
                text = text.replace(needle, insert, 1)
    path.write_text(text, encoding="utf-8", newline="\n")
    print("patched", path.relative_to(ROOT))


def patch_main() -> None:
    path = ROOT / "backend/main.py"
    text = path.read_text(encoding="utf-8")
    if "admin_live_offers" not in text:
        text = text.replace(
            "from routes.live_auctions import router as live_auctions_router\n",
            "from routes.live_auctions import router as live_auctions_router\n"
            "from routes.admin_live_offers import router as admin_live_offers_router\n"
            "from routes.live_offers import router as live_offers_router\n",
        )
        text = text.replace(
            "app.include_router(live_auctions_router)\n",
            "app.include_router(live_auctions_router)\n"
            "app.include_router(admin_live_offers_router)\n"
            "app.include_router(live_offers_router)\n",
        )
    path.write_text(text, encoding="utf-8", newline="\n")
    print("patched", path.relative_to(ROOT))


def patch_conftest() -> None:
    path = ROOT / "backend/tests/conftest.py"
    text = path.read_text(encoding="utf-8")
    if "models_live_offer" not in text:
        text = text.replace(
            "import models_live_auction  # noqa: F401 — register live sales tables",
            "import models_live_auction  # noqa: F401 — register live sales tables\n"
            "import models_live_offer  # noqa: F401 — register live offer tables",
        )
    path.write_text(text, encoding="utf-8", newline="\n")
    print("patched", path.relative_to(ROOT))


def run() -> None:
    main()
    patch_models_live()
    patch_db_migrate()
    patch_admin_rbac()
    patch_main()
    patch_conftest()


if __name__ == "__main__":
    run()

